      out.write("    if (sid) {\r\n");
      out.write("        supportIds.add(sid);\r\n");
      out.write("    }\r\n");
      out.write("});\r\n");
      out.write("\r\n");
      out.write("function addSupportRecruiter() {\r\n");
      out.write("    var sel = document.getElementById('addSupportSelect');\r\n");
      out.write("    if (!sel) return;\r\n");
      out.write("    var id = sel.value;\r\n");
      out.write("    if (!id) {\r\n");
      out.write("        if (window.showToast) {\r\n");
      out.write("            window.showToast('Vui lòng chọn recruiter từ danh sách trước khi nhấn Thêm!', 'warning', 'Chưa chọn recruiter');\r\n");
      out.write("        } else {\r\n");
