      out.write("    var title = opt.getAttribute('data-title') || '';\r\n");
      out.write("    var dept = opt.getAttribute('data-dept') || '';\r\n");
      out.write("\r\n");
      out.write("    // Kiểm tra trùng với danh sách hỗ trợ\r\n");
      out.write("    if (supportIds.has(id)) {\r\n");
      out.write("        if (window.showToast) {\r\n");
      out.write("            window.showToast('Recruiter này đã có trong danh sách hỗ trợ!', 'warning', 'Đã tồn tại');\r\n");
      out.write("        } else {\r\n");
      out.write("            alert('Recruiter này đã có trong danh sách hỗ trợ!');\r\n");
      out.write("        }\r\n");
      out.write("        return;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    // Kiểm tra trùng với recruiter chính\r\n");
      out.write("    var primarySel = document.getElementById('primaryRecruiterId');\r\n");
      out.write("    if (primarySel && primarySel.value === id) {\r\n");
      out.write("        if (window.showToast) {\r\n");
      out.write("            window.showToast('Recruiter này hiện đang là recruiter chính! Không thể thêm vào danh sách hỗ trợ.', 'warning', 'Trùng recruiter chính');\r\n");
      out.write("        } else {\r\n");
      out.write("            alert('Recruiter này hiện đang là recruiter chính! Không thể thêm vào hỗ trợ.');\r\n");
