      out.write("            '<input type=\"hidden\" name=\"supportRecruiterIds\" value=\"' + escapeHtml(id) + '\">' +\r\n");
      out.write("            '<button type=\"button\" class=\"btn btn-sm btn-outline-danger py-1 px-2\" onclick=\"removeSupportItem(this)\" title=\"Xóa khỏi danh sách\">' +\r\n");
      out.write("                '<i class=\"bi bi-trash3\"></i>' +\r\n");
      out.write("            '</button>' +\r\n");
      out.write("        '</div>';\r\n");
