      out.write("        empty.classList.toggle('d-none', supportIds.size > 0);\r\n");
      out.write("    }\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// Khi người dùng đổi Recruiter chính, nếu người đó đang nằm trong danh sách hỗ trợ thì tự động gỡ khỏi hỗ trợ\r\n");
      out.write("var primarySel = document.getElementById('primaryRecruiterId');\r\n");
      out.write("if (primarySel) {\r\n");
      out.write("    primarySel.addEventListener('change', function() {\r\n");
      out.write("        var val = this.value;\r\n");
      out.write("        if (val && supportIds.has(val)) {\r\n");
      out.write("            var item = document.querySelector('.support-item[data-id=\"' + val + '\"]');\r\n");
      out.write("            if (item) {\r\n");
      out.write("                var btn = item.querySelector('button');\r\n");
      out.write("                if (btn) {\r\n");
      out.write("                    removeSupportItem(btn);\r\n");
      out.write("                    if (window.showToast) {\r\n");
      out.write("                        window.showToast('Recruiter này được chọn làm Recruiter chính nên đã tự động đưa ra khỏi danh sách hỗ trợ.', 'info', 'Tự động điều chỉnh', 4000);\r\n");
      out.write("                    }\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("        }\r\n");
      out.write("    });\r\n");
      out.write("}\r\n");
      out.write("\r\n");
